<script setup lang="ts">
import { errorMessage } from '@/utils'
import {ref,onMounted} from 'vue'
import {useSettingsStore} from '@/stores/settings'
import {workspace,plain} from '@/utils/workspace-api'
import {DEFAULT_MODULE_PREFERENCES,type PreferenceModule} from '@/types/workspace'
import {useDocumentsStore} from '@/stores/documents'
const props=defineProps<{module:PreferenceModule;section?:string}>(),settings=useSettingsStore(),documents=useDocumentsStore()
const value=ref(structuredClone(DEFAULT_MODULE_PREFERENCES)),directory=ref(''),tags=ref(''),assetCategories=ref(''),experienceCategories=ref(''),busy=ref(false),error=ref(''),saved=ref(false)
onMounted(async()=>{try{value.value=await workspace.preferences.get(props.module);tags.value=value.value.defaultTags.join('、');assetCategories.value=value.value.assetCategories.join('、');experienceCategories.value=value.value.experienceCategories.join('、');if(props.module==='document'){directory.value=await workspace.preferences.dataDirectory();await documents.refresh()}}catch(e){error.value=errorMessage(e)}})
const split=(text:string)=>[...new Set(text.split(/[、,，\n]/).map(x=>x.trim()).filter(Boolean))]
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';saved.value=false;try{await fn()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function save(){await run(async()=>{value.value=await workspace.preferences.save(props.module,{...plain(value.value),defaultTags:split(tags.value),assetCategories:split(assetCategories.value),experienceCategories:split(experienceCategories.value)});saved.value=true})}
</script>
<template><section class="ws ws-card module-preferences"><h3>{{ $t("{p0}偏好", {p0: (module==='document'?$t('资料'):module==='personal'?$t('个人'):$t('项目'))}) }}</h3><p class="ws-muted">{{ $t("仅作用于当前模块。模型引用全局已有配置，凭据在全局设置中维护。") }}</p><div class="ws-form">
<template v-if="!section || section === 'scan'"><label>{{ $t("使用模型") }}<select v-model="value.profileId" :aria-label="$t('模块模型')"><option value="">{{ $t("继承全局当前模型") }}</option><option v-for="profile in settings.settings.ai_profiles" :key="profile.id" :value="profile.id">{{profile.name}} · {{profile.model}}</option><option v-if="value.profileId&&!settings.settings.ai_profiles.some(p=>p.id===value.profileId)" :value="value.profileId">{{ $t("原配置已删除，请重新选择") }}</option></select></label><p class="ws-muted">{{ $t("共享模型配置可在顶部「全局」→「AI 配置」维护。") }}</p><label>{{ $t("助手工作偏好") }}<textarea v-model="value.instructions" maxlength="2000" :placeholder="$t('例如：回答简洁，保留来源；按实际发生时间记录。')"/></label></template>
<template v-if="module==='document'"><template v-if="!section || section === 'organize'"><h3>{{ $t("资料目录") }}</h3><p class="ws-path">{{directory||$t('尚未设置')}}</p><p class="ws-muted">{{ $t("用于项目复制/移动到抱一及源文件回收。更换目录不会自动搬迁已有文件；恢复旧记录时需选回原目录。") }}</p><button class="ws-button" :disabled="busy" @click="run(async()=>{directory=(await workspace.preferences.chooseDataDirectory())||directory})">{{ $t("选择资料数据目录") }}</button></template><template v-if="!section || section === 'scan'"><h3>{{ $t("导入默认值") }}</h3><label>{{ $t("在全部分类导入时默认归入") }}<select v-model="value.defaultCategory"><option value="">{{ $t("不指定，先进入其他") }}</option><option v-for="category in documents.categories" :key="category.id" :value="category.id">{{category.name}}</option></select></label><label>{{ $t("新导入资料的默认标签") }}<input v-model="tags" :placeholder="$t('用顿号或逗号分隔')"/></label></template><div v-if="!section || section === 'reader'" class="ws-two"><label>{{ $t("阅读字号") }}<input v-model.number="value.fontSize" type="number" min="12" max="28"/></label><label>{{ $t("PDF 默认缩放") }}<input v-model.number="value.pdfZoom" type="number" min="0.7" max="2" step="0.1"/></label></div></template>
<template v-if="module==='personal'"><label>{{ $t("资产分类") }}<input v-model="assetCategories" :placeholder="$t('用顿号分隔')"/></label><label>{{ $t("经历分类") }}<input v-model="experienceCategories" :placeholder="$t('用顿号分隔')"/></label><label>{{ $t("到期提醒提前天数") }}<input v-model.number="value.remindDays" type="number" min="0" max="365"/></label><label class="check"><input v-model="value.showCompleted" type="checkbox"/>{{ $t("显示已完成待办") }}</label><p class="ws-muted">{{ $t("开启后默认显示全部待办；今日、逾期和已完成等筛选仍按你的选择显示。") }}</p><label class="check"><input v-model="value.showCounts" type="checkbox"/>{{ $t("总览显示资源库数量") }}</label></template>
<p v-if="error" class="ws-error" role="alert">{{$systemMessage(error)}}</p><div class="ws-toolbar"><button class="ws-button primary" :disabled="busy" @click="save">{{ $t("保存模块偏好") }}</button><span v-if="saved" role="status">{{ $t("已保存") }}</span></div></div></section></template>
<style scoped>.module-preferences{margin-bottom:24px}.module-preferences h3{margin:0 0 12px}.module-preferences .ws-form{max-width:700px}.module-preferences .ws-path{overflow-wrap:anywhere}</style>
